<template><div class="modal-backdrop" @mousedown.self="$emit('close')"><form class="modal invite-dialog" @submit.prevent="$emit('send',form)"><div class="modal-head"><div><h2>Convidar para o workspace</h2><p>Compartilhe <strong>{{workspace}}</strong> com sua equipe.</p></div><button type="button" @click="$emit('close')"><X/></button></div><label>E-mail<input v-model="form.email" type="email" placeholder="nome@email.com" required/></label><div class="modal-fields"><label>Cargo/função<input v-model="form.job" required/></label><label>Permissão<select v-model="form.role"><option>Membro</option><option>Administrador</option></select></label></div><button class="primary-btn invite-send"><Send/>Enviar convite</button><section class="invite-link-section"><div><strong>Link de convite</strong><small>Entrada em {{workspace}}</small></div><div class="invite-link"><span>{{link}}</span><button type="button" @click="copy"><Copy/>{{copied?'✓ Link copiado':'Copiar link'}}</button></div><div class="invite-link-actions"><label><input v-model="enabled" type="checkbox"/>Permitir entrada através deste link</label><button type="button" @click="regenerate"><RefreshCw/>Regenerar link</button></div></section></form></div></template>
<script setup lang="ts">import{computed,reactive,ref}from"vue";import{Copy,RefreshCw,Send,X}from"lucide-vue-next";defineProps<{workspace:string}>();defineEmits(["close","send"]);const form=reactive({email:"",job:"",role:"Membro"}),enabled=ref(true),code=ref(Math.random().toString(36).slice(2,8).toUpperCase()),copied=ref(false),link=computed(()=>`https://taskflow.app/invite/${code.value}`);async function copy(){await navigator.clipboard.writeText(link.value);copied.value=true}function regenerate(){code.value=Math.random().toString(36).slice(2,8).toUpperCase()}</script>
